$draft=$catalog;$draft['translations'][0]['status']='draft';localeAssert(Localization::localizedCatalog($draft)['apps']===[],'Draft not public');$hidden=$catalog;$hidden['apps']=[];localeAssert(Localization::localizedCatalog($hidden)['apps']===[],'Hidden base unavailable');
