localeAssert(str_contains($en,'<html lang="en"')&&str_contains($en,'"inLanguage":"en"'),'Language metadata');localeAssert(str_contains($en,'rel="canonical" href="https://catalog.example.org/catalog/en/apps/example-app"'),'Self canonical');localeAssert(str_contains($en,'<h1>Example app</h1>')&&!str_contains($en,'Türkçe açıklama'),'No body fallback');localeAssert(str_contains(PublicSite::sitemap($catalog,$config),'/en/apps/example-app'),'Translated sitemap');localeAssert(!str_contains(PublicSite::sitemap($stale,$config),'/en/apps/example-app'),'Stale excluded sitemap');
